            "E30b98a3ffeda561f:0:699",
            "E30b98a3ffeda561f:699:1399"
          ],
          "condicoes": [
            "constatação em instalações específicas fiscalizadas pela ANP",
            "contexto de avaliação da adequação e disponibilidade de recursos de resposta e de seus planos de inspeção, teste e manutenção"
          ],
          "limites": [
            "não informa efeito quantitativo sobre vazão, pressão, demanda simultânea ou redundância da rede",
            "não detalha arranjo hidráulico, bombas, jockey ou caixas de mar"
          ]
        },
        {
          "proposicao": "Em teste de partida citado no relatório, uma bomba de combate a incêndio não funcionou, e o achado foi tratado conjuntamente com corrosão elevada nas linhas, indicando comprometimento da disponibilidade dos recursos de resposta.",
          "trechos": [
            "E30b98a3ffeda561f:699:1399"
          ],
          "condicoes": [
            "resultado observado durante teste em instalação específica",
            "interpretação vinculada ao juízo fiscalizatório sobre disponibilidade dos sistemas e equipamentos de emergência"
